const out = [];

for (const item of $input.all()) {
  const bin = item.binary || {};

  for (const key of Object.keys(bin)) {
    const file = bin[key];
    const mime = String(file.mimeType || '').toLowerCase();

    if (!mime.includes('pdf') && !mime.startsWith('image/')) {
      continue;
    }

    out.push({
      json: {
        ghiChu: item.json?.ghi_chu || '',
        submittedAt: item.json?.submittedAt || '',
        fileName: file.fileName || key,
        mimeType: mime,
        isPdf: mime.includes('pdf'),
      },
      binary: {
        data: file,
      },
    });
  }
}

return out;

const out = [];

for (const item of $input.all()) {
  const bin = item.binary || {};
  const j = item.json || {};

  const emailMeta = {
    emailId: j.id,
    emailSubject: j.subject || '',
    emailFrom: j.from?.value?.[0]?.address || '',
    emailDate: j.date || '',
  };

  for (const key of Object.keys(bin)) {
    const file = bin[key];
    const mime = String(file.mimeType || '').toLowerCase();

    if (!mime.includes('pdf') && !mime.startsWith('image/')) {
      continue;
    }

    out.push({
      json: {
        ...emailMeta,
        fileName: file.fileName || key,
        mimeType: mime,
        isPdf: mime.includes('pdf'),
      },
      binary: {
        data: file,
      },
    });
  }
}

return out;

const inv = $('AI trích xuất hóa đơn').first().json.output || {};
const src = $('Chuẩn hoá file hóa đơn').first().json;
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/[^a-z0-9]/g, '');
const stripCo = (s) => norm(s).replace(/congty|tnhh|cophan|ctcp|mtv|trachnhiemhuuhan/g, '');
const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0 && r['Số PO'] !== undefined);
const open = (r) => !String(r['Trạng thái'] || '').toLowerCase().includes('đã đóng');
let match = null;
let how = '';
if (inv.so_po_tham_chieu) {
  match = rows.find((r) => norm(r['Số PO']) && norm(r['Số PO']) === norm(inv.so_po_tham_chieu));
  if (match) how = 'Theo số PO trên hóa đơn';
}
if (!match && inv.mst_nha_cung_cap) {
  const c = rows.filter((r) => open(r) && norm(r['MST NCC']) && norm(r['MST NCC']) === norm(inv.mst_nha_cung_cap));
  if (c.length) { match = c[c.length - 1]; how = c.length > 1 ? 'Theo MST NCC (PO mới nhất trong ' + c.length + ' PO)' : 'Theo MST NCC'; }
}
if (!match && inv.nha_cung_cap) {
  const key = stripCo(inv.nha_cung_cap);
  const c = rows.filter((r) => open(r) && key && stripCo(r['Nhà cung cấp']) === key);
  if (c.length) { match = c[c.length - 1]; how = 'Theo tên nhà cung cấp'; }
}
return [{ json: { invoice: inv, email: { id: src.emailId, subject: src.emailSubject, from: src.emailFrom, fileName: src.fileName }, po: match, poFound: !!match, cachKhop: match ? how : 'Không tìm thấy PO' } }];

